import{_ as g,C as c,c as p,o as a,j as d,G as n,a8 as t,b as s,a as o,w as i,a9 as r}from"./chunks/framework.8HQ-OgOa.js";const S=JSON.parse('{"title":"Plugin Development Guide","description":"Plugin Development Guide","frontmatter":{"date":"2026-05-05T00:00:00.000Z","author":["Makitoid","Qoder"],"title":"Plugin Development Guide","description":"Plugin Development Guide"},"headers":[],"relativePath":"en/dev/dev-guide/plugin-dev/index.md","filePath":"en/dev/dev-guide/plugin-dev/index.md"}'),h={name:"en/dev/dev-guide/plugin-dev/index.md"};function m(P,e,v,f,A,I){const u=c("ArticleMetadata"),l=c("Mermaid");return a(),p("div",null,[e[4]||(e[4]=d("h1",{id:"plugin-development-guide",tabindex:"-1"},[o("Plugin Development Guide "),d("a",{class:"header-anchor",href:"#plugin-development-guide","aria-label":'Permalink to "Plugin Development Guide"'},"​")],-1)),n(u),e[5]||(e[5]=t('<h2 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h2><p>This guide is intended for developers who want to develop plugins based on the Ink Canvas platform. It systematically explains plugin interface design and implementation, usage of host services, plugin lifecycle management, view interfaces, configuration systems, debugging and testing, packaging and distribution, security precautions, and practical recommendations for common plugin scenarios. The content is based on the actual SDK and host implementations in the repository to help you quickly get started and build stable and reliable plugins.</p><h2 id="project-structure" tabindex="-1">Project Structure <a class="header-anchor" href="#project-structure" aria-label="Permalink to &quot;Project Structure&quot;">​</a></h2><p>The Ink Canvas plugin architecture consists of two parts: the &quot;Plugin SDK&quot; and the &quot;Host Application&quot;:</p><ul><li>The Plugin SDK provides the <code>IPlugin</code> interface, the host interface <code>IPluginHost</code>, the base class <code>PluginBase</code>, service interfaces (such as <code>IInkCanvasService</code> and <code>IAppRestartService</code>), and the plugin metadata model <code>PluginInfo</code>.</li><li>The Host Application is responsible for loading plugins, registering services, exposing UI and settings entries, and managing the plugin collection uniformly via <code>PluginManager</code>.</li></ul>',5)),(a(),s(r,null,{default:i(()=>[n(l,{id:"mermaid-27",class:"mermaid",graph:"graph%20TB%0Asubgraph%20%22Plugin%20SDK%22%0AIPlugin%5B%22IPlugin%20Interface%22%5D%0AIHost%5B%22IPluginHost%20Host%20Interface%22%5D%0ABase%5B%22PluginBase%20Abstract%20Base%20Class%22%5D%0AInfo%5B%22PluginInfo%20Plugin%20Metadata%22%5D%0ASvc1%5B%22IInkCanvasService%22%5D%0ASvc2%5B%22IAppRestartService%22%5D%0Aend%0Asubgraph%20%22Host%20Application%22%0AApp%5B%22App.xaml.cs%20Application%20Entry%22%5D%0AMW%5B%22MainWindow.xaml.cs%20Main%20Window%22%5D%0APM%5B%22Plugins%2FPluginManager.cs%20Plugin%20Manager%22%5D%0AUISet%5B%22PluginPage.xaml%3Cbr%2F%3EPluginSettingsPage.xaml%3Cbr%2F%3EStoragePage.xaml%22%5D%0AExt%5B%22Helpers%2FExternalCallerLauncher.cs%22%5D%0Aend%0AApp%20--%3E%20PM%0APM%20--%3E%20IPlugin%0APM%20--%3E%20IHost%0APM%20--%3E%20Info%0AApp%20--%3E%20Svc1%0AApp%20--%3E%20Svc2%0AMW%20--%3E%20PM%0AUISet%20--%3E%20PM%0AExt%20--%3E%20PM%0A"})]),fallback:i(()=>e[0]||(e[0]=[o(" Loading... ",-1)])),_:1})),e[6]||(e[6]=t('<h2 id="core-components" tabindex="-1">Core Components <a class="header-anchor" href="#core-components" aria-label="Permalink to &quot;Core Components&quot;">​</a></h2><ul><li><code>IPlugin</code>: Defines plugin identifiers, metadata, lifecycle, and view interfaces.</li><li><code>IPluginHost</code>: Provides logging, exception recording, and service registration/retrieval capabilities.</li><li><code>PluginBase</code>: Provides default empty implementations and convenient access to host services.</li><li><code>PluginInfo</code>: Carries plugin instances, load status, and metadata.</li><li>Service Interfaces: <code>IInkCanvasService</code> and <code>IAppRestartService</code>, used to interact with the host.</li></ul><h2 id="architecture-overview" tabindex="-1">Architecture Overview <a class="header-anchor" href="#architecture-overview" aria-label="Permalink to &quot;Architecture Overview&quot;">​</a></h2><p>The plugin system adopts the mode of &quot;Interface-Driven + Host-Managed&quot;:</p><ul><li>Plugins expose metadata and lifecycle hooks via <code>IPlugin</code>.</li><li>The host registers services (such as <code>IInkCanvasService</code> and <code>IAppRestartService</code>) during the startup phase, and loads plugins via <code>PluginManager</code>.</li><li>Plugins retrieve services, record logs, and provide views via <code>IPluginHost</code>.</li><li>The host UI (settings page) displays the plugin list and settings views.</li></ul>',5)),(a(),s(r,null,{default:i(()=>[n(l,{id:"mermaid-86",class:"mermaid",graph:"sequenceDiagram%0Aparticipant%20App%20as%20%22App.xaml.cs%22%0Aparticipant%20PM%20as%20%22PluginManager%22%0Aparticipant%20Host%20as%20%22IPluginHost%22%0Aparticipant%20Plugin%20as%20%22IPlugin%20Instance%22%0Aparticipant%20Svc%20as%20%22Service%20Interface%22%0AApp-%3E%3EPM%20%3A%20Initialize%20%26%20scan%20plugin%20directory%0APM-%3E%3EPlugin%20%3A%20Call%20Initialize(Host)%0APlugin-%3E%3EHost%20%3A%20Register%2FGet%20service%20(GetService%3CT%3E)%0APlugin-%3E%3EHost%20%3A%20Record%20log%20(Log%2FLogError)%0AApp-%3E%3EPM%20%3A%20Register%20service%20(RegisterService%3CT%3E)%0APM--%3E%3EApp%20%3A%20Expose%20plugin%20list%20(Plugins)%0APlugin-%3E%3EPlugin%20%3A%20Shutdown()%20lifecycle%20ends%0A"})]),fallback:i(()=>e[1]||(e[1]=[o(" Loading... ",-1)])),_:1})),e[7]||(e[7]=t('<h2 id="component-details" tabindex="-1">Component Details <a class="header-anchor" href="#component-details" aria-label="Permalink to &quot;Component Details&quot;">​</a></h2><h3 id="iplugin-interface-and-lifecycle" tabindex="-1">IPlugin Interface and Lifecycle <a class="header-anchor" href="#iplugin-interface-and-lifecycle" aria-label="Permalink to &quot;IPlugin Interface and Lifecycle&quot;">​</a></h3><ul><li>Identification &amp; Metadata: <code>Id</code>, <code>Name</code>, <code>Version</code>, <code>Description</code>, <code>Author</code>, <code>Order</code>.</li><li>Lifecycle: <code>Initialize(host)</code>, <code>Shutdown()</code>.</li><li>View Interfaces: <code>GetMainView()</code>, <code>GetSettingsView()</code>, used by the host to inject UI.</li></ul>',3)),(a(),s(r,null,{default:i(()=>[n(l,{id:"mermaid-110",class:"mermaid",graph:"classDiagram%0Aclass%20IPlugin%20%7B%0A%2Bstring%20Id%0A%2Bstring%20Name%0A%2Bstring%20Version%0A%2Bstring%20Description%0A%2Bstring%20Author%0A%2Bint%20Order%0A%2BInitialize(host)%20void%0A%2BShutdown()%20void%0A%2BGetMainView()%20object%0A%2BGetSettingsView()%20object%0A%7D%0Aclass%20PluginBase%20%7B%0A-IPluginHost%20Host%0A%2BInitialize(host)%20void%0A%2BShutdown()%20void%0A%2BGetMainView()%20object%0A%2BGetSettingsView()%20object%0A%23Log(message)%20void%0A%23LogError(message%2C%20ex)%20void%0A%23GetService%3CT%3E()%20T%0A%7D%0Aclass%20PluginInfo%20%7B%0A%2Bstring%20Id%0A%2Bstring%20Name%0A%2Bstring%20Version%0A%2Bstring%20Description%0A%2Bstring%20Author%0A%2Bint%20Order%0A%2BIPlugin%20Instance%0A%2Bbool%20IsLoaded%0A%7D%0APluginBase%20..%7C%3E%20IPlugin%0A"})]),fallback:i(()=>e[2]||(e[2]=[o(" Loading... ",-1)])),_:1})),e[8]||(e[8]=t('<h3 id="ipluginhost-and-service-registration" tabindex="-1">IPluginHost and Service Registration <a class="header-anchor" href="#ipluginhost-and-service-registration" aria-label="Permalink to &quot;IPluginHost and Service Registration&quot;">​</a></h3><ul><li>Logs: <code>Log(message)</code>, <code>LogError(message, ex)</code>.</li><li>Services: <code>RegisterService&lt;T&gt;(service)</code>, <code>GetService&lt;T&gt;()</code>.</li></ul><p>The host registers services during application startup for plugins to use.</p><h3 id="plugin-base-class-pluginbase" tabindex="-1">Plugin Base Class PluginBase <a class="header-anchor" href="#plugin-base-class-pluginbase" aria-label="Permalink to &quot;Plugin Base Class PluginBase&quot;">​</a></h3><ul><li>Default Empty Implementations: <code>Initialize</code>/<code>Shutdown</code>/<code>GetMainView</code>/<code>GetSettingsView</code>.</li><li>Convenient Methods: <code>Log</code>, <code>LogError</code>, <code>GetService&lt;T&gt;</code>, which delegate internally to the host.</li></ul><h3 id="plugin-management-and-loading-host-side" tabindex="-1">Plugin Management and Loading (Host Side) <a class="header-anchor" href="#plugin-management-and-loading-host-side" aria-label="Permalink to &quot;Plugin Management and Loading (Host Side)&quot;">​</a></h3><ul><li><code>PluginManager</code>: Maintains the plugin directory, loads plugins, and exposes the <code>Plugins</code> list.</li><li>Plugin Directory: Located in the <code>Plugins</code> folder under the application base directory.</li></ul><h3 id="host-service-examples" tabindex="-1">Host Service Examples <a class="header-anchor" href="#host-service-examples" aria-label="Permalink to &quot;Host Service Examples&quot;">​</a></h3><ul><li><code>IInkCanvasService</code>: Open/close whiteboard, async whiteboard opening.</li><li><code>IAppRestartService</code>: Restart the application with different privilege levels, restart after switching topmost mode.</li></ul><h3 id="plugin-ui-and-settings-entries" tabindex="-1">Plugin UI and Settings Entries <a class="header-anchor" href="#plugin-ui-and-settings-entries" aria-label="Permalink to &quot;Plugin UI and Settings Entries&quot;">​</a></h3><ul><li>Plugin List and Settings Page: <code>PluginPage.xaml</code>, <code>PluginSettingsPage.xaml</code>.</li><li>Storage page displays plugin space usage and prompts.</li></ul><h3 id="external-calls-and-plugin-interaction" tabindex="-1">External Calls and Plugin Interaction <a class="header-anchor" href="#external-calls-and-plugin-interaction" aria-label="Permalink to &quot;External Calls and Plugin Interaction&quot;">​</a></h3><ul><li><code>ExternalCallerLauncher</code>: Provides the <code>classisland://</code> plugin call URI, allowing external clients to trigger plugin actions.</li></ul><h2 id="dependency-analysis" tabindex="-1">Dependency Analysis <a class="header-anchor" href="#dependency-analysis" aria-label="Permalink to &quot;Dependency Analysis&quot;">​</a></h2><ul><li>Plugins depend on <code>IPlugin</code> and <code>IPluginHost</code>; they can be implemented quickly via <code>PluginBase</code>.</li><li>The host depends on <code>PluginManager</code> to manage plugins; it registers services like <code>IInkCanvasService</code> and <code>IAppRestartService</code> at the same time.</li><li>The UI layer displays plugin status and settings views through settings pages.</li></ul>',15)),(a(),s(r,null,{default:i(()=>[n(l,{id:"mermaid-219",class:"mermaid",graph:"graph%20LR%0AIPlugin%20--%3E%20PluginBase%0AIPluginHost%20--%3E%20PluginBase%0APluginBase%20--%3E%20App%0AApp%20--%3E%20PluginManager%0APluginManager%20--%3E%20IPlugin%0AApp%20--%3E%20IInkCanvasService%0AApp%20--%3E%20IAppRestartService%0AUI%5B%22PluginPage%2FPluginSettingsPage%2FStoragePage%22%5D%20--%3E%20PluginManager%0A"})]),fallback:i(()=>e[3]||(e[3]=[o(" Loading... ",-1)])),_:1})),e[9]||(e[9]=t('<h2 id="performance-considerations" tabindex="-1">Performance Considerations <a class="header-anchor" href="#performance-considerations" aria-label="Permalink to &quot;Performance Considerations&quot;">​</a></h2><ul><li>Plugin Lifecycle: Perform one-time initialization in <code>Initialize</code> as much as possible; release resources in <code>Shutdown</code> to avoid memory leaks.</li><li>View Interfaces: Objects returned by <code>GetMainView</code>/<code>GetSettingsView</code> should be lightweight and reusable; avoid performing time-consuming operations in the UI thread.</li><li>Service Calling: Retrieve services via <code>IPluginHost.GetService&lt;T&gt;()</code> to reduce direct dependencies on hardcoded types.</li><li>Logs: Use <code>Host.Log</code>/<code>LogError</code> to output critical information, facilitating the location of performance bottlenecks.</li></ul><h2 id="troubleshooting-guide" tabindex="-1">Troubleshooting Guide <a class="header-anchor" href="#troubleshooting-guide" aria-label="Permalink to &quot;Troubleshooting Guide&quot;">​</a></h2><ul><li>Plugin Not Loaded: Check the plugin directory and <code>PluginManager</code> initialization logic; check host log outputs.</li><li>Service Unavailable: Confirm that the host has called <code>RegisterService&lt;T&gt;</code> in the startup phase; retrieve via <code>GetService&lt;T&gt;()</code> on the plugin side.</li><li>UI Not Displayed: Confirm that <code>GetMainView</code>/<code>GetSettingsView</code> returns valid objects; check settings page bindings.</li><li>External Call Failed: Verify the URI format in <code>ExternalCallerLauncher</code> and the target plugin implementation.</li></ul><h2 id="conclusion" tabindex="-1">Conclusion <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusion&quot;">​</a></h2><p>Through the <code>IPlugin</code> interface and the <code>IPluginHost</code> host interface, combined with the quick implementation of <code>PluginBase</code> and the unified management of <code>PluginManager</code>, the Ink Canvas plugin system realizes a clear separation of responsibilities and excellent extensibility. Together with service registration, UI settings entries, and external calling mechanisms, developers can efficiently build plugin scenarios such as tool extensions, UI customization, and data processing.</p><h2 id="appendix" tabindex="-1">Appendix <a class="header-anchor" href="#appendix" aria-label="Permalink to &quot;Appendix&quot;">​</a></h2><h3 id="plugin-project-template-and-structure-recommendations" tabindex="-1">Plugin Project Template and Structure Recommendations <a class="header-anchor" href="#plugin-project-template-and-structure-recommendations" aria-label="Permalink to &quot;Plugin Project Template and Structure Recommendations&quot;">​</a></h3><ul><li>It is recommended to use <code>IPlugin</code> in the SDK as the contract, inheriting <code>PluginBase</code> for fast implementation.</li><li>Refer to the existing plugin directory <code>Plugins</code> for project structure, organizing plugin DLLs and resources as needed.</li><li>Ensure that <code>PluginManager</code> can scan and load the plugin directory correctly during the host startup phase.</li></ul><h3 id="plugin-host-service-checklist" tabindex="-1">Plugin Host Service Checklist <a class="header-anchor" href="#plugin-host-service-checklist" aria-label="Permalink to &quot;Plugin Host Service Checklist&quot;">​</a></h3><ul><li>Register Service: Call <code>RegisterService&lt;T&gt;</code> during application startup, passing the specific service instance.</li><li>Retrieve Service: Get required services via <code>GetService&lt;T&gt;()</code> in the plugin&#39;s <code>Initialize</code>.</li><li>Common Services: <code>IInkCanvasService</code>, <code>IAppRestartService</code>.</li></ul><h3 id="plugin-configuration-system" tabindex="-1">Plugin Configuration System <a class="header-anchor" href="#plugin-configuration-system" aria-label="Permalink to &quot;Plugin Configuration System&quot;">​</a></h3><ul><li>Config File Location: Typically located at <code>Configs/Settings.json</code> in the application root directory.</li><li>Parameter Verification: Read and verify necessary configuration items in the plugin&#39;s <code>Initialize</code>, setting default values.</li><li>Default Values: Use reasonable default values and log warnings when configurations are missing.</li></ul><h3 id="plugin-debugging-and-testing" tabindex="-1">Plugin Debugging and Testing <a class="header-anchor" href="#plugin-debugging-and-testing" aria-label="Permalink to &quot;Plugin Debugging and Testing&quot;">​</a></h3><ul><li>Unit Testing: Write unit tests for pure logic classes (without UI), mocking <code>IPluginHost</code> behavior.</li><li>Integration Testing: Load plugins in the host application, validating <code>Initialize</code>/<code>Shutdown</code> and view interfaces.</li><li>Logs: Output critical paths and exception details using <code>Host.Log</code>/<code>LogError</code>.</li></ul><h3 id="plugin-packaging-and-distribution" tabindex="-1">Plugin Packaging and Distribution <a class="header-anchor" href="#plugin-packaging-and-distribution" aria-label="Permalink to &quot;Plugin Packaging and Distribution&quot;">​</a></h3><ul><li>Version Management: Adhere to the <code>IPlugin.Version</code> field specification, unifying the version number format.</li><li>Dependency Declaration: Ensure that plugin DLLs and dependencies are in the same directory; avoid failures in resolving assemblies at runtime.</li><li>Installer: Put plugin DLLs into the host&#39;s <code>Plugins</code> directory; provide uninstall scripts to clean up resources.</li></ul><h3 id="plugin-security-considerations" tabindex="-1">Plugin Security Considerations <a class="header-anchor" href="#plugin-security-considerations" aria-label="Permalink to &quot;Plugin Security Considerations&quot;">​</a></h3><ul><li>Permission Control: Leverage the privilege switching capabilities of <code>IAppRestartService</code> to elevate permissions cautiously.</li><li>Sandbox Mechanism: Avoid direct access to sensitive system resources; collaborate with the host through service interfaces.</li><li>Malicious Code Protection: Strictly validate external inputs and URI parameters; minimize the plugin&#39;s permission scope.</li></ul><h3 id="examples-of-common-plugin-scenarios" tabindex="-1">Examples of Common Plugin Scenarios <a class="header-anchor" href="#examples-of-common-plugin-scenarios" aria-label="Permalink to &quot;Examples of Common Plugin Scenarios&quot;">​</a></h3><ul><li>Tool Extensions: Open/close whiteboards via <code>IInkCanvasService</code>, or interact with other tools.</li><li>UI Customization: Implement <code>GetMainView</code>/<code>GetSettingsView</code>, providing custom controls and settings pages.</li><li>Data Processing: Subscribe to events or read configurations in <code>Initialize</code>, processing and persisting data.</li></ul><p>Source of Chapter</p>',22))])}const x=g(h,[["render",m]]);export{S as __pageData,x as default};
